        ImageOps.DrawLine(released[216], new Point(offset + 0, offset + 9), new Point(offset + 10, offset + 9), GoodReleasedColour);
        ImageOps.DrawLine(released[216], new Point(offset + 0, offset + 0), new Point(offset + 2, offset + 0), GoodReleasedColour);
        ImageOps.DrawLine(released[216], new Point(offset + 4, offset + 0), new Point(offset + 6, offset + 0), GoodReleasedColour);
        ImageOps.DrawLine(released[216], new Point(offset + 8, offset + 0), new Point(offset + 10, offset + 0), GoodReleasedColour);

        // Cyrillic SHCHA
        released[217] = Create(11 + offset * 2, 12 + offset * 2, released[217]);
        ImageOps.Copy(released[216], new Rect(0, 0, released[216].Width, released[216].Height), released[217], new Point(0, 0));
        ImageOps.DrawLine(released[217], new Point(offset + 10, offset + 10), new Point(offset + 10, offset + 11), GoodReleasedColour);

        // b, Cyrillic hard sign
        released[218] = Create(10 + offset * 2, 10 + offset * 2, released[218]);
        ImageOps.DrawLine(released[218], new Point(offset + 0, offset + 0), new Point(offset + 3, offset + 0), GoodReleasedColour);
        ImageOps.DrawLine(released[218], new Point(offset + 2, offset + 9), new Point(offset + 8, offset + 9), GoodReleasedColour);
        ImageOps.DrawLine(released[218], new Point(offset + 3, offset + 1), new Point(offset + 3, offset + 8), GoodReleasedColour);
        ImageOps.DrawLine(released[218], new Point(offset + 4, offset + 4), new Point(offset + 8, offset + 4), GoodReleasedColour);
        ImageOps.DrawLine(released[218], new Point(offset + 9, offset + 5), new Point(offset + 9, offset + 8), GoodReleasedColour);

        // bI, Cyrillic YERU
        released[219] = Create(10 + offset * 2, 10 + offset * 2, released[219]);
        ImageOps.DrawLine(released[219], new Point(offset + 0, offset + 0), new Point(offset + 2, offset + 0), GoodReleasedColour);
        ImageOps.DrawLine(released[219], new Point(offset + 0, offset + 9), new Point(offset + 4, offset + 9), GoodReleasedColour);
        ImageOps.DrawLine(released[219], new Point(offset + 1, offset + 1), new Point(offset + 1, offset + 8), GoodReleasedColour);
        ImageOps.DrawLine(released[219], new Point(offset + 2, offset + 4), new Point(offset + 4, offset + 4), GoodReleasedColour);
        ImageOps.DrawLine(released[219], new Point(offset + 5, offset + 5), new Point(offset + 5, offset + 8), GoodReleasedColour);
        ImageOps.Copy(released[73], new Rect(offset + 1, 0, released[73].Width - 2 - offset * 2, released[73].Height), released[219], new Point(offset + 7, 0));

        // b, Cyrillic soft sign
        released[220] = Create(8 + offset * 2, 10 + offset * 2, released[220]);
        ImageOps.DrawLine(released[220], new Point(offset + 0, offset + 0), new Point(offset + 2, offset + 0), GoodReleasedColour);
        ImageOps.DrawLine(released[220], new Point(offset + 0, offset + 9), new Point(offset + 6, offset + 9), GoodReleasedColour);
        ImageOps.DrawLine(released[220], new Point(offset + 1, offset + 1), new Point(offset + 1, offset + 8), GoodReleasedColour);
        ImageOps.DrawLine(released[220], new Point(offset + 2, offset + 4), new Point(offset + 6, offset + 4), GoodReleasedColour);
        ImageOps.DrawLine(released[220], new Point(offset + 7, offset + 5), new Point(offset + 7, offset + 8), GoodReleasedColour);

        // Flipped C with line inside, Cyrillic E
        released[221] = Create(8 + offset * 2, 10 + offset * 2, released[221]);
        ImageOps.DrawLine(released[221], new Point(offset + 2, offset + 0), new Point(offset + 5, offset + 0), GoodReleasedColour);
        ImageOps.DrawLine(released[221], new Point(offset + 7, offset + 2), new Point(offset + 7, offset + 7), GoodReleasedColour);
        ImageOps.DrawLine(released[221], new Point(offset + 2, offset + 9), new Point(offset + 5, offset + 9), GoodReleasedColour);
        ImageOps.DrawLine(released[221], new Point(offset + 0, offset + 0), new Point(offset + 0, offset + 2), GoodReleasedColour);
        ImageOps.DrawLine(released[221], new Point(offset + 2, offset + 4), new Point(offset + 6, offset + 4), GoodReleasedColour);
        ImageOps.SetPixel(released[221], offset + 0, offset + 7, GoodReleasedColour);
        ImageOps.SetPixel(released[221], offset + 1, offset + 1, GoodReleasedColour);
        ImageOps.SetPixel(released[221], offset + 1, offset + 8, GoodReleasedColour);
        ImageOps.SetPixel(released[221], offset + 6, offset + 1, GoodReleasedColour);
        ImageOps.SetPixel(released[221], offset + 6, offset + 8, GoodReleasedColour);

        // Ukrainian IE. Make it by mirroring horizontally the previous letter.
        released[170] = Create(8 + offset * 2, 10 + offset * 2, released[170]);
        ImageOps.FlipRegion(released[221], released[221].Image.Bounds, released[170], Point.Zero, true, false);

        // IO, Cyrillic YU
        released[222] = Create(11 + offset * 2, 10 + offset * 2, released[222]);
        ImageOps.Copy(released[73], new Rect(offset + 1, 0, released[73].Width - 2 - offset * 2, released[73].Height), released[222], new Point(offset + 0, 0));
        ImageOps.Copy(released[79], new Rect(offset, 0, 3, released[79].Height), released[222], new Point(offset + 4, 0));
        ImageOps.Copy(released[79], new Rect(offset + 6, 0, 4, released[79].Height), released[222], new Point(offset + 7, 0));
        ImageOps.DrawLine(released[222], new Point(offset + 2, offset + 4), new Point(offset + 3, offset + 4), GoodReleasedColour);

        // Mirrored R, Cyrillic YA
        released[223] = Create(released[208].Width, released[208].Height, released[223]);
        ImageOps.FlipRegion(released[208], new Rect(0, 0, released[208].Width, released[208].Height), released[223], new Point(0, 0), true, false);
        ImageOps.DrawLine(released[223], new Point(offset + 0, offset + 9), new Point(offset + 2, offset + 9), GoodReleasedColour);
        ImageOps.DrawLine(released[223], new Point(offset + 3, offset + 6), new Point(offset + 1, offset + 8), GoodReleasedColour);

        // Cyrillic Capital Lje
        released[138] = Create(released[203].Width + released[220].Width - 8, released[203].Height, released[138]);
        ImageOps.Copy(released[203], new Rect(0, 0, released[203].Width, released[203].Height), released[138], new Point(0, 0));
        ImageOps.Copy(released[220], new Rect(2, 0, released[220].Width - 2, released[220].Height), released[138], new Point(released[203].Width - 6, 0));
        ImageOps.FillTransform(released[138], new Rect(7, 3, 1, 1), 1);
        released[138] = Moved(released[138], released[203].OffsetX, released[203].OffsetY);

        // Cyrillic Capital Nje
        released[140] = Create(released[205].Width + released[220].Width - 7, released[205].Height, released[140]);
        ImageOps.Copy(released[205], new Rect(0, 0, released[205].Width, released[205].Height), released[140], new Point(0, 0));
        ImageOps.Copy(released[220], new Rect(3, 0, released[220].Width - 4, released[220].Height), released[140], new Point(released[205].Width - 4, 0));
        released[140] = Moved(released[140], released[205].OffsetX, released[205].OffsetY);
    }
}
